import { useCallback } from 'react';
import { NativeAuthnResult, WebAuthnFirstStepRes } from '~/entities/biometric/model/types';
import { WebViewBridgeResponse } from '~/shared/@types/webview-bridge';
import { NativeFunction } from '~/shared/constants/native-function';

type NativeBiometricResponse = {
  data: WebAuthnFirstStepRes;
} & WebViewBridgeResponse;

type BiometricCertificationParams = {
  webAuthnOptions: PublicKeyCredentialRequestOptions;
  username: string;
};

export const useAuthnNativeCertification = () => {
  // 생체인증 요청 (네이티브 통신만 담당)
  const certification = useCallback(
    async ({ webAuthnOptions, username }: BiometricCertificationParams): Promise<NativeAuthnResult> => {
      return new Promise<NativeAuthnResult>((resolve, reject) => {
        // 앱이 아닌 경우 실행하지 않음
        if (!window.ReactNativeWebView) {
          reject(new Error('네이티브 환경이 아닙니다.'));
          return;
        }

        // 네이티브에 WebAuthn options와 username 전달
        window.webViewBridge.send(NativeFunction.BiometricCertification, {
          webAuthnOptions,
          username,
          success: (response: NativeBiometricResponse) => {
            resolve(response.data);
          },
          error: (nativeError: any) => {
            console.error('네이티브 생체인증 에러:', nativeError);
            //사용자가 취소 버튼을 눌렀을 경우
            if (nativeError?.data?.errorType === 'USER_CANCEL' || nativeError.data?.errorMessage?.contains('cancel')) {
              return;
            }
            reject(new Error(nativeError));
          },
        });
      });
    },
    [],
  );

  return {
    certification,
  };
};
