import { Suspense, useEffect, lazy } from 'react';
import { useStore } from '~/app/store/store';
import { SuperAppEncData } from '~/entities/super-app/model/types';
import { useSetOnBack } from '~/widgets/sub-layout/use-sub-layout';
import { BiometricCertification } from '~/entities/biometric/ui/biometric-certification';
import { useGetRouterState } from '~/entities/exchange/lib/use-get-router-state';
import { PIN_CONSTANTS } from '~/entities/pin/lib/constants';
import { PinInterfaceProps } from '~/entities/pin/model/types';
import { PinInputMessage } from '~/entities/pin/ui/pin-input-message';
import { PinInteractionMode } from '~/shared/api/dtos/enums';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { PATHS } from '~/shared/routes/paths';

const PinKeyboard = lazy(() =>
  import('~/entities/pin/ui/pin-keyboard').then((module) => ({
    default: module.PinKeyboard,
  })),
);

export const PinInterface = (props: PinInterfaceProps) => {
  const { routerState: backState } = useGetRouterState<SuperAppEncData>();
  const { navigate, navigateBack } = useNavigate();

  // Store에서 상태와 액션을 가져옴
  const initializeWithProps = useStore.getState().pinSlice.initializeWithProps;
  const setCallbacks = useStore.getState().pinSlice.setCallbacks;

  // 컴포넌트 마운트 시 초기 상태 설정 및 콜백 등록
  useEffect(() => {
    // 상태 초기화
    initializeWithProps({
      title: props.title,
      message: props.message,
      step: props.step,
      prevPin: props.prevPin,
      type: props.type,
    });

    // 콜백 등록
    setCallbacks({
      onCompleteInput: props.handleCompleteInput,
      onCancel: props.handleCancelClick,
      onError: props.handleVerifyError,
      onMaxFailure: props.handleMaxFailure,
    });

    // 컴포넌트 언마운트 시 상태 초기화
    return () => {
      useStore.getState().pinSlice.resetAll();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleSecondStepBack = () => {
    initializeWithProps({
      prevPin: '',
      step: PIN_CONSTANTS.STEP.FIRST,
      title: props.title,
      message: props.message,
      type: props.type,
    });
  };

  const handleFirstStepBack = () => {
    const typeToActionMap = {
      [PinInteractionMode.신규입력]: () => navigate(PATHS.signUp.arsNumber, { replace: true, state: { ...backState } }),
      [PinInteractionMode.재설정]: () => navigateBack(),
      [PinInteractionMode.로그인]: () => {},
      [PinInteractionMode.인증]: () => {},
      [PinInteractionMode.인증_바텀시트]: () => {},
      default: () => navigateBack(),
    };

    const action = typeToActionMap[props.type as PinInteractionMode] || typeToActionMap.default;
    action();
  };

  const pinBack = () => {
    const isNewOrResetMode = props.type === PinInteractionMode.신규입력 || props.type === PinInteractionMode.재설정;
    const isSecondStep = isNewOrResetMode && props.step === PIN_CONSTANTS.STEP.SECOND;

    return isSecondStep ? handleSecondStepBack() : handleFirstStepBack();
  };

  const shouldUseBackHandler = ![PinInteractionMode.인증_바텀시트, PinInteractionMode.인증].includes(
    props.type as PinInteractionMode,
  );

  const isBiometricCertification =
    props.type === PinInteractionMode.인증 ||
    props.type === PinInteractionMode.로그인 ||
    props.type === PinInteractionMode.인증_바텀시트;

  // Register back handler conditionally
  if (shouldUseBackHandler) {
    // eslint-disable-next-line react-hooks/rules-of-hooks
    useSetOnBack(pinBack);
  }

  return (
    <div className="sub">
      <div className="keypad-wrap">
        <PinInputMessage />
        <BiometricCertification isEnabled={isBiometricCertification} type={props.type!} />
        <div className="keypad-list relative w-full" style={{ minHeight: '60vh' }}>
          <Suspense fallback={<div className="flex h-[60vh] w-full items-center justify-center"></div>}>
            <PinKeyboard type={props.type} />
          </Suspense>
        </div>
      </div>
    </div>
  );
};
