import { useStore } from '~/app/store/store';
import { useAuthentication } from '~/entities/biometric/lib/use-authentication';
import { PinInteractionMode } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';

type biometricCertificationProp = {
  isEnabled: boolean;
  type: PinInteractionMode;
};

export const BiometricCertification = ({ isEnabled, type }: biometricCertificationProp) => {
  const triggerCompleteInput = useStore.getState().pinSlice.triggerCompleteInput;
  const { authenticate } = useAuthentication();
  const { openAlertDialog } = useAlertDialog();

  const handleBiometricCertification = () => {
    authenticate(
      {
        success: () => {
          triggerCompleteInput();
        },
        error: (error: string) => {
          openAlertDialog({
            title: i18n.t('pin:titleBiometricAuthError'),
            message: error,
          });
        },
      },
      type,
    );
  };

  if (!isEnabled) {
    return <></>;
  }

  return <button onClick={handleBiometricCertification}>{i18n.t('pin:biometricAuth')}</button>;
};
