import { Player } from '@lottiefiles/react-lottie-player';
import { memo } from 'react';
import { useShallow } from 'zustand/react/shallow';
import { useStore } from '~/app/store/store';
import KeypadAni from '~/shared/assets/img/lottie/keypad_ani.json';

export const PinInputMessage = memo(function PinInputMessage() {
  const [pin, title, message, isError] = useStore(
    useShallow((s) => [s.pinSlice.pin, s.pinSlice.title, s.pinSlice.message, s.pinSlice.isError]),
  );

  return (
    <div className="keypad-top">
      <h3>{title}</h3>
      <p className={isError ? 'on-fail' : ''}>
        {message?.split('\n')?.map((item, index) =>
          index > 0 ? (
            <span key={`span_${index}`}>
              <br />
              {item}
            </span>
          ) : (
            item
          ),
        )}
      </p>
      <div className="keypad-pin">
        {[...Array(6)].map((i, index) => (
          <label key={`label_${index}`} className={`pin-box ${pin.length > index ? 'on' : ''}`}>
            <input type="hidden" id={`num${index}`} value={pin.length > index ? pin.substring(index, index + 1) : ''} />
            <span className={pin.length > index ? 'on' : ''}>
              {pin.length > index ? pin.substring(index, index + 1) : ''}
            </span>
          </label>
        ))}
      </div>
      <div className="secure-info">
        <Player
          src={KeypadAni}
          background="transparent"
          style={{ width: '220px', height: 'auto' }}
          autoplay={true}
          speed={1}
          keepLastFrame={true}
        />
      </div>
    </div>
  );
});
